CREATE OR REPLACE FUNCTION public.indicadores_guard_metric() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE historical boolean; BEGIN IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.source_metadata:=OLD.source_metadata; END IF; historical:=coalesce(NEW.source_metadata->>'origin'='okr_tracker' AND EXISTS(SELECT 1 FROM public.indicadores_import_records r WHERE r.source_table='key_results' AND r.source_id=NEW.id AND (r.data->>'target')::numeric=NEW.target_value),false); IF trim(NEW.title)='' OR (NEW.initial_value=NEW.target_value AND NOT historical) THEN RAISE EXCEPTION 'Informe um nome e uma meta diferente do valor inicial.'; END IF; IF NEW.responsible_id IS NULL AND NOT historical THEN RAISE EXCEPTION 'Informe o responsável.'; END IF; IF NEW.measure='binary' AND (NEW.initial_value<>0 OR NEW.target_value<>1 OR NEW.current_value NOT IN(0,1)) THEN RAISE EXCEPTION 'Marco usa Não feito (0) ou Feito (1).'; END IF; IF NEW.objective_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_objectives o JOIN public.indicadores_cycles c ON c.id=o.cycle_id WHERE o.id=NEW.objective_id AND c.archived) THEN RAISE EXCEPTION 'O ciclo está arquivado.'; END IF; RETURN NEW; END $$;